mapper.update:
UPDATE notice n
SET view_count = NVL(n.view_count, 0) + 1
WHERE n.notice_id = #{notice_id}

mapper.delete:
DELETE FROM notice_files f
WHERE f.notice_id = #{notice_id}
  AND f.notice_file_id = #{notice_file_id}
  AND EXISTS (
      SELECT 1
      FROM notice n
      WHERE n.notice_id = f.notice_id
        AND n.deleted IS NULL
        AND NVL(n.status, 1) != 0

  )
